// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Check whether first-run setup is needed
	// (GET /auth/bootstrap)
	GetBootstrapStatus(w http.ResponseWriter, r *http.Request)
	// Create the first administrator
	// (POST /auth/bootstrap)
	Bootstrap(w http.ResponseWriter, r *http.Request)
	// Log in and establish a session
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// OIDC provider callback
	// (GET /auth/oidc/callback)
	OidcCallback(w http.ResponseWriter, r *http.Request, params OidcCallbackParams)
	// Exchange a one-time OIDC code for a session
	// (POST /auth/oidc/exchange)
	ExchangeOidcCode(w http.ResponseWriter, r *http.Request)
	// List configured OIDC providers
	// (GET /auth/oidc/providers)
	ListOidcProviders(w http.ResponseWriter, r *http.Request)
	// Start an OIDC login
	// (GET /auth/oidc/start)
	StartOidc(w http.ResponseWriter, r *http.Request, params StartOidcParams)
	// Rotate the caller's bearer token
	// (POST /auth/refresh)
	RefreshToken(w http.ResponseWriter, r *http.Request)
	// Inspect the current session
	// (GET /auth/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// List the caller's sessions and devices
	// (GET /auth/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// Revoke one of the caller's sessions
	// (DELETE /auth/sessions/{sessionId})
	RevokeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// Get one audiobook's detail
	// (GET /books/{pid})
	GetBook(w http.ResponseWriter, r *http.Request, pid Pid)
	// Where the caller left off in a book
	// (GET /books/{pid}/resume)
	GetBookResume(w http.ResponseWriter, r *http.Request, pid Pid)
	// Replace the caller's playback settings for a book
	// (PUT /books/{pid}/settings)
	PutBookSettings(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get one episode's detail
	// (GET /episodes/{pid})
	GetEpisode(w http.ResponseWriter, r *http.Request, pid Pid)
	// Remove an episode's fetched audio from the server
	// (DELETE /episodes/{pid}/fetch)
	RemoveEpisodeDownload(w http.ResponseWriter, r *http.Request, pid Pid)
	// Fetch an episode's audio to the server
	// (POST /episodes/{pid}/fetch)
	FetchEpisode(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get an episode's transcript
	// (GET /episodes/{pid}/transcript)
	GetEpisodeTranscript(w http.ResponseWriter, r *http.Request, pid Pid)
	// Liveness and version probe
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Get one item's detail
	// (GET /items/{pid})
	GetItem(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get artwork
	// (GET /items/{pid}/art)
	GetItemArt(w http.ResponseWriter, r *http.Request, pid Pid, params GetItemArtParams)
	// Resolve an offline download for an item
	// (GET /items/{pid}/download-info)
	GetDownloadInfo(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get an item's lyrics
	// (GET /items/{pid}/lyrics)
	GetItemLyrics(w http.ResponseWriter, r *http.Request, pid Pid)
	// Resolve a playable stream for an item
	// (GET /items/{pid}/play-info)
	GetPlayInfo(w http.ResponseWriter, r *http.Request, pid Pid, params GetPlayInfoParams)
	// Get the caller's playback state for an item
	// (GET /items/{pid}/play-state)
	GetPlayState(w http.ResponseWriter, r *http.Request, pid Pid)
	// Checkpoint the caller's playback position
	// (PUT /items/{pid}/play-state)
	PutPlayState(w http.ResponseWriter, r *http.Request, pid Pid)
	// Rate an item
	// (PUT /items/{pid}/rating)
	SetRating(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get an item's silence skip map
	// (GET /items/{pid}/skip-map)
	GetSkipMap(w http.ResponseWriter, r *http.Request, pid Pid, params GetSkipMapParams)
	// Star or unstar an item
	// (PUT /items/{pid}/star)
	SetStar(w http.ResponseWriter, r *http.Request, pid Pid)
	// Get one job's state
	// (GET /jobs/{pid})
	GetJob(w http.ResponseWriter, r *http.Request, pid Pid)
	// List libraries
	// (GET /libraries)
	ListLibraries(w http.ResponseWriter, r *http.Request)
	// Browse a discovery list
	// (GET /library/browse)
	BrowseList(w http.ResponseWriter, r *http.Request, params BrowseListParams)
	// Browse library items
	// (GET /library/items)
	ListItems(w http.ResponseWriter, r *http.Request, params ListItemsParams)
	// Start a library rescan
	// (POST /library/rescan)
	RescanLibrary(w http.ResponseWriter, r *http.Request)
	// Search the library
	// (GET /library/search)
	Search(w http.ResponseWriter, r *http.Request, params SearchParams)
	// Report listen sessions
	// (POST /listens)
	ReportListens(w http.ResponseWriter, r *http.Request)
	// Read the caller's playback state for many items
	// (POST /play-states)
	ListPlayStates(w http.ResponseWriter, r *http.Request)
	// List the caller's podcast subscriptions
	// (GET /podcasts)
	ListSubscriptions(w http.ResponseWriter, r *http.Request, params ListSubscriptionsParams)
	// Subscribe to a podcast
	// (POST /podcasts)
	SubscribePodcast(w http.ResponseWriter, r *http.Request)
	// Export the caller's subscriptions as OPML
	// (GET /podcasts/opml)
	ExportOpml(w http.ResponseWriter, r *http.Request)
	// Import subscriptions from OPML
	// (POST /podcasts/opml)
	ImportOpml(w http.ResponseWriter, r *http.Request)
	// Unsubscribe from a show
	// (DELETE /podcasts/{pid})
	UnsubscribePodcast(w http.ResponseWriter, r *http.Request, pid Pid, params UnsubscribePodcastParams)
	// Get one show with the caller's subscription state
	// (GET /podcasts/{pid})
	GetPodcast(w http.ResponseWriter, r *http.Request, pid Pid)
	// List a show's episodes
	// (GET /podcasts/{pid}/episodes)
	ListEpisodes(w http.ResponseWriter, r *http.Request, pid Pid, params ListEpisodesParams)
	// Refresh a show's feed now
	// (POST /podcasts/{pid}/refresh)
	RefreshPodcast(w http.ResponseWriter, r *http.Request, pid Pid)
	// Replace the caller's settings for a subscription
	// (PUT /podcasts/{pid}/settings)
	PutSubscriptionSettings(w http.ResponseWriter, r *http.Request, pid Pid)
	// Mirror the catalog (snapshot or changed-since delta)
	// (GET /sync/catalog)
	SyncCatalog(w http.ResponseWriter, r *http.Request, params SyncCatalogParams)
	// Mirror the caller's server-side state (changed-since delta)
	// (GET /sync/server)
	SyncServer(w http.ResponseWriter, r *http.Request, params SyncServerParams)
	// List accounts
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// Create an account
	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// List the caller's app passwords
	// (GET /users/me/app-passwords)
	ListAppPasswords(w http.ResponseWriter, r *http.Request)
	// Create an app password
	// (POST /users/me/app-passwords)
	CreateAppPassword(w http.ResponseWriter, r *http.Request)
	// Revoke an app password
	// (DELETE /users/me/app-passwords/{appPasswordId})
	RevokeAppPassword(w http.ResponseWriter, r *http.Request, appPasswordId AppPasswordId)
	// Get the caller's preferences
	// (GET /users/me/prefs)
	GetPrefs(w http.ResponseWriter, r *http.Request)
	// Replace the caller's preferences
	// (PUT /users/me/prefs)
	PutPrefs(w http.ResponseWriter, r *http.Request)
	// Delete an account
	// (DELETE /users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// Get one account
	// (GET /users/{userId})
	GetUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// Update an account
	// (PATCH /users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// Set an account's password
	// (PUT /users/{userId}/password)
	SetPassword(w http.ResponseWriter, r *http.Request, userId UserId)
	// Revoke all of an account's sessions
	// (DELETE /users/{userId}/sessions)
	RevokeUserSessions(w http.ResponseWriter, r *http.Request, userId UserId)
}

