// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Check whether first-run setup is needed
	// (GET /auth/bootstrap)
	GetBootstrapStatus(ctx context.Context, request GetBootstrapStatusRequestObject) (GetBootstrapStatusResponseObject, error)
	// Create the first administrator
	// (POST /auth/bootstrap)
	Bootstrap(ctx context.Context, request BootstrapRequestObject) (BootstrapResponseObject, error)
	// Log in and establish a session
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// OIDC provider callback
	// (GET /auth/oidc/callback)
	OidcCallback(ctx context.Context, request OidcCallbackRequestObject) (OidcCallbackResponseObject, error)
	// Exchange a one-time OIDC code for a session
	// (POST /auth/oidc/exchange)
	ExchangeOidcCode(ctx context.Context, request ExchangeOidcCodeRequestObject) (ExchangeOidcCodeResponseObject, error)
	// List configured OIDC providers
	// (GET /auth/oidc/providers)
	ListOidcProviders(ctx context.Context, request ListOidcProvidersRequestObject) (ListOidcProvidersResponseObject, error)
	// Start an OIDC login
	// (GET /auth/oidc/start)
	StartOidc(ctx context.Context, request StartOidcRequestObject) (StartOidcResponseObject, error)
	// Rotate the caller's bearer token
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// Inspect the current session
	// (GET /auth/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// List the caller's sessions and devices
	// (GET /auth/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// Revoke one of the caller's sessions
	// (DELETE /auth/sessions/{sessionId})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// Get one audiobook's detail
	// (GET /books/{pid})
	GetBook(ctx context.Context, request GetBookRequestObject) (GetBookResponseObject, error)
	// Where the caller left off in a book
	// (GET /books/{pid}/resume)
	GetBookResume(ctx context.Context, request GetBookResumeRequestObject) (GetBookResumeResponseObject, error)
	// Replace the caller's playback settings for a book
	// (PUT /books/{pid}/settings)
	PutBookSettings(ctx context.Context, request PutBookSettingsRequestObject) (PutBookSettingsResponseObject, error)
	// Get one episode's detail
	// (GET /episodes/{pid})
	GetEpisode(ctx context.Context, request GetEpisodeRequestObject) (GetEpisodeResponseObject, error)
	// Remove an episode's fetched audio from the server
	// (DELETE /episodes/{pid}/fetch)
	RemoveEpisodeDownload(ctx context.Context, request RemoveEpisodeDownloadRequestObject) (RemoveEpisodeDownloadResponseObject, error)
	// Fetch an episode's audio to the server
	// (POST /episodes/{pid}/fetch)
	FetchEpisode(ctx context.Context, request FetchEpisodeRequestObject) (FetchEpisodeResponseObject, error)
	// Get an episode's transcript
	// (GET /episodes/{pid}/transcript)
	GetEpisodeTranscript(ctx context.Context, request GetEpisodeTranscriptRequestObject) (GetEpisodeTranscriptResponseObject, error)
	// Liveness and version probe
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Get one item's detail
	// (GET /items/{pid})
	GetItem(ctx context.Context, request GetItemRequestObject) (GetItemResponseObject, error)
	// Get artwork
	// (GET /items/{pid}/art)
	GetItemArt(ctx context.Context, request GetItemArtRequestObject) (GetItemArtResponseObject, error)
	// Resolve an offline download for an item
	// (GET /items/{pid}/download-info)
	GetDownloadInfo(ctx context.Context, request GetDownloadInfoRequestObject) (GetDownloadInfoResponseObject, error)
	// Get an item's lyrics
	// (GET /items/{pid}/lyrics)
	GetItemLyrics(ctx context.Context, request GetItemLyricsRequestObject) (GetItemLyricsResponseObject, error)
	// Resolve a playable stream for an item
	// (GET /items/{pid}/play-info)
	GetPlayInfo(ctx context.Context, request GetPlayInfoRequestObject) (GetPlayInfoResponseObject, error)
	// Get the caller's playback state for an item
	// (GET /items/{pid}/play-state)
	GetPlayState(ctx context.Context, request GetPlayStateRequestObject) (GetPlayStateResponseObject, error)
	// Checkpoint the caller's playback position
	// (PUT /items/{pid}/play-state)
	PutPlayState(ctx context.Context, request PutPlayStateRequestObject) (PutPlayStateResponseObject, error)
	// Rate an item
	// (PUT /items/{pid}/rating)
	SetRating(ctx context.Context, request SetRatingRequestObject) (SetRatingResponseObject, error)
	// Get an item's silence skip map
	// (GET /items/{pid}/skip-map)
	GetSkipMap(ctx context.Context, request GetSkipMapRequestObject) (GetSkipMapResponseObject, error)
	// Star or unstar an item
	// (PUT /items/{pid}/star)
	SetStar(ctx context.Context, request SetStarRequestObject) (SetStarResponseObject, error)
	// Get one job's state
	// (GET /jobs/{pid})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// List libraries
	// (GET /libraries)
	ListLibraries(ctx context.Context, request ListLibrariesRequestObject) (ListLibrariesResponseObject, error)
	// Browse a discovery list
	// (GET /library/browse)
	BrowseList(ctx context.Context, request BrowseListRequestObject) (BrowseListResponseObject, error)
	// Browse library items
	// (GET /library/items)
	ListItems(ctx context.Context, request ListItemsRequestObject) (ListItemsResponseObject, error)
	// Start a library rescan
	// (POST /library/rescan)
	RescanLibrary(ctx context.Context, request RescanLibraryRequestObject) (RescanLibraryResponseObject, error)
	// Search the library
	// (GET /library/search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// Report listen sessions
	// (POST /listens)
	ReportListens(ctx context.Context, request ReportListensRequestObject) (ReportListensResponseObject, error)
	// Read the caller's playback state for many items
	// (POST /play-states)
	ListPlayStates(ctx context.Context, request ListPlayStatesRequestObject) (ListPlayStatesResponseObject, error)
	// List the caller's podcast subscriptions
	// (GET /podcasts)
	ListSubscriptions(ctx context.Context, request ListSubscriptionsRequestObject) (ListSubscriptionsResponseObject, error)
	// Subscribe to a podcast
	// (POST /podcasts)
	SubscribePodcast(ctx context.Context, request SubscribePodcastRequestObject) (SubscribePodcastResponseObject, error)
	// Export the caller's subscriptions as OPML
	// (GET /podcasts/opml)
	ExportOpml(ctx context.Context, request ExportOpmlRequestObject) (ExportOpmlResponseObject, error)
	// Import subscriptions from OPML
	// (POST /podcasts/opml)
	ImportOpml(ctx context.Context, request ImportOpmlRequestObject) (ImportOpmlResponseObject, error)
	// Unsubscribe from a show
	// (DELETE /podcasts/{pid})
	UnsubscribePodcast(ctx context.Context, request UnsubscribePodcastRequestObject) (UnsubscribePodcastResponseObject, error)
	// Get one show with the caller's subscription state
	// (GET /podcasts/{pid})
	GetPodcast(ctx context.Context, request GetPodcastRequestObject) (GetPodcastResponseObject, error)
	// List a show's episodes
	// (GET /podcasts/{pid}/episodes)
	ListEpisodes(ctx context.Context, request ListEpisodesRequestObject) (ListEpisodesResponseObject, error)
	// Refresh a show's feed now
	// (POST /podcasts/{pid}/refresh)
	RefreshPodcast(ctx context.Context, request RefreshPodcastRequestObject) (RefreshPodcastResponseObject, error)
	// Replace the caller's settings for a subscription
	// (PUT /podcasts/{pid}/settings)
	PutSubscriptionSettings(ctx context.Context, request PutSubscriptionSettingsRequestObject) (PutSubscriptionSettingsResponseObject, error)
	// Mirror the catalog (snapshot or changed-since delta)
	// (GET /sync/catalog)
	SyncCatalog(ctx context.Context, request SyncCatalogRequestObject) (SyncCatalogResponseObject, error)
	// Mirror the caller's server-side state (changed-since delta)
	// (GET /sync/server)
	SyncServer(ctx context.Context, request SyncServerRequestObject) (SyncServerResponseObject, error)
	// List accounts
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// Create an account
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// List the caller's app passwords
	// (GET /users/me/app-passwords)
	ListAppPasswords(ctx context.Context, request ListAppPasswordsRequestObject) (ListAppPasswordsResponseObject, error)
	// Create an app password
	// (POST /users/me/app-passwords)
	CreateAppPassword(ctx context.Context, request CreateAppPasswordRequestObject) (CreateAppPasswordResponseObject, error)
	// Revoke an app password
	// (DELETE /users/me/app-passwords/{appPasswordId})
	RevokeAppPassword(ctx context.Context, request RevokeAppPasswordRequestObject) (RevokeAppPasswordResponseObject, error)
	// Get the caller's preferences
	// (GET /users/me/prefs)
	GetPrefs(ctx context.Context, request GetPrefsRequestObject) (GetPrefsResponseObject, error)
	// Replace the caller's preferences
	// (PUT /users/me/prefs)
	PutPrefs(ctx context.Context, request PutPrefsRequestObject) (PutPrefsResponseObject, error)
	// Delete an account
	// (DELETE /users/{userId})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// Get one account
	// (GET /users/{userId})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// Update an account
	// (PATCH /users/{userId})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
	// Set an account's password
	// (PUT /users/{userId}/password)
	SetPassword(ctx context.Context, request SetPasswordRequestObject) (SetPasswordResponseObject, error)
	// Revoke all of an account's sessions
	// (DELETE /users/{userId}/sessions)
	RevokeUserSessions(ctx context.Context, request RevokeUserSessionsRequestObject) (RevokeUserSessionsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

